package com.employeesystem.emsbackend.controller; import com.employeesystem.emsbackend.dto.*; import com.employeesystem.emsbackend.service.CalendarEventService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/calendar-events") @RequiredArgsConstructor public class CalendarEventController { private final CalendarEventService service; @GetMapping public List<CalendarEventResponseDTO> list(){return service.list();} @PostMapping @PreAuthorize("hasAnyRole('ADMIN','HR')") public ResponseEntity<CalendarEventResponseDTO> create(@Valid @RequestBody CalendarEventRequestDTO request){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(request));} @DeleteMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','HR')") public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();} }
